257	export async function runCodeEvaluators({ task, candidateWorkspace, hiddenWorkspace, typecheckBaselineWorkspace, agent, baselineSnapshot }) {
258	  if (!task.evaluators || !Array.isArray(task.evaluators) || task.evaluators.length === 0) return [];
259	  const results = [];
260	  let changedFiles = null;
261	  let changedFilesError = null;
262	  if (task.evaluators.some((entry) => ["syntax_ast", "diff_boundary"].includes(typeof entry === "string" ? entry : entry?.type))) {
263	    try { changedFiles = changedWorkspacePaths(baselineSnapshot, candidateWorkspace); }
264	    catch (error) { changedFilesError = String(error?.message ?? error); }
265	  }
266	  let pinnedWorkspace = null;
267	  let pinnedWorkspaceRoot = null;
268	  let pinnedWorkspaceError = null;
269	  if (needsEvaluatorConfigurationBaseline(task)) {
270	    try {
271	      const pinned = createPinnedCandidateWorkspace(typecheckBaselineWorkspace, candidateWorkspace);
272	      pinnedWorkspace = pinned.workspace;
273	      pinnedWorkspaceRoot = pinned.tempRoot;
274	    } catch (error) {
275	      pinnedWorkspaceError = String(error?.message ?? error);
276	    }
277	  }
278	  try {
279	    for (const item of task.evaluators) {
280	      const spec = typeof item === "string" ? { type: item } : item;
281	      if (!spec || typeof spec.type !== "string") continue;
282	      switch (spec.type) {
283	        case "syntax_ast": {
284	          if (changedFilesError) {
285	            results.push(evaluatorResult("syntax_ast", false, 0, { error: changedFilesError, files: [] }));
286	          } else {
287	            const files = spec.files ?? changedFiles.filter((relative) => {
288	              if (!isSupportedSyntaxPath(relative)) return false;
289	              try { fs.lstatSync(path.join(candidateWorkspace, ...relative.split("/"))); return true; }
290	              catch (error) { return error?.code !== "ENOENT"; }
291	            });
292	            if (spec.files === undefined && files.length === 0) {
293	              results.push(evaluatorResult("syntax_ast", true, 1, { files: [], failures: [] }));
294	            } else {
295	              results.push(await evaluateSyntaxAst({ root: candidateWorkspace, files, parsers: spec.parsers }));
296	            }
297	          }
298	          break;
299	        }
300	        case "diff_boundary": {
301	          if (changedFilesError) {
302	            results.push(evaluatorResult("diff_boundary", false, 0, { error: changedFilesError, accepted: [], violations: [] }));
303	          } else {
304	            const allowedPaths = spec.allowedPaths ?? task.allowedPaths ?? [];
305	            results.push(evaluateDiffBoundary({ changedFiles, allowedPaths }));
306	          }
307	          break;
308	        }
309	        case "json_repair_rate": {
310	          results.push(evaluateJsonRepairRate(agent?.json?.turn?.toolCallSyntax));
311	          break;
312	        }
313	        case "build": {
314	          const command = spec.command ?? task.build?.command;
315	          const args = spec.args ?? task.build?.args ?? [];
316	          const timeoutMs = spec.timeoutMs ?? task.build?.timeoutMs;
317	          if (!command) results.push(evaluatorResult("build", false, 0, { error: "no build command specified" }));
318	          else if (!pinnedWorkspace) results.push(evaluatorResult("build", false, 0, { error: pinnedWorkspaceError ?? "no pre-agent build configuration workspace is available" }));
319	          else results.push(await evaluateBuild({ command, args, cwd: pinnedWorkspace, timeoutMs }));
320	          break;
321	        }
322	        case "typecheck_clean": {
323	          const explicitBaseline = spec.baseline ?? task.typecheck?.baseline;
324	          const baseSpec = explicitBaseline ?? (typecheckBaselineWorkspace ? {
325	            command: spec.command ?? task.typecheck?.command,
326	            args: spec.args ?? task.typecheck?.args ?? [],
327	            cwd: typecheckBaselineWorkspace,
328	          } : null);
329	          const candidateSpec = spec.candidate ?? task.typecheck?.candidate ?? { command: spec.command ?? task.typecheck?.command, args: spec.args ?? task.typecheck?.args ?? [], cwd: candidateWorkspace };
330	          const candSpec = { ...candidateSpec, cwd: pinnedWorkspace ?? candidateWorkspace };
331	          if (!baseSpec?.command || !candSpec?.command) results.push(evaluatorResult("typecheck_clean", false, 0, { error: explicitBaseline ? "no typecheck command specified" : "no pre-agent typecheck baseline workspace" }));
332	          else if (!pinnedWorkspace) results.push(evaluatorResult("typecheck_clean", false, 0, { error: pinnedWorkspaceError ?? "no pre-agent build configuration workspace is available" }));
333	          else results.push(await evaluateTypecheckClean({ baseline: baseSpec, candidate: candSpec }));
334	          break;
335	        }
336	        default:
337	          results.push(evaluatorResult(spec.type, false, 0, { error: `unknown evaluator type: ${spec.type}` }));
338	          break;
339	      }
340	    }
341	  } finally {
342	    if (pinnedWorkspaceRoot) fs.rmSync(pinnedWorkspaceRoot, { recursive: true, force: true });
343	  }
344	  return results;
345	}
